package com.dvopenlabs.freedom.setup;

import java.io.*;
import java.nio.file.Files;
import java.util.*;
import org.json.*;

/** Reviewed transaction engine. Reconnect checks state; it never retries an uncertain mutation. */
final class PhoneInstaller {
    interface Device {
        boolean trusted();String peer();String fingerprint()throws Exception;String home()throws Exception;int api()throws Exception;List<String> apps()throws Exception;
        JSONObject installed(File save)throws Exception;void install(File apk,String hash)throws Exception;void preserveHome(String home)throws Exception;void launch()throws Exception;JSONObject nativeCall(String method,JSONObject value)throws Exception;
    }
    final Device device;final JSONObject release;final File apk,root;final SetupJournal journal;JSONObject reviewed;
    PhoneInstaller(Device d,JSONObject release,File apk,File root)throws Exception{device=d;this.release=new JSONObject(release.toString());this.apk=apk;this.root=root;root.mkdirs();journal=new SetupJournal(root);}
    void trusted(){if(!device.trusted())throw new IllegalStateException("Confirm the paired TV identity first");}
    String releaseHash()throws Exception{return SetupPolicy.sha(SetupPolicy.canonical(release).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
    JSONObject nativeStatus()throws Exception{JSONObject s=device.nativeCall("status",null);if(s.optInt("api")!=1||!SetupPolicy.PACKAGE.equals(s.optString("package")))throw new IOException("Unsupported native setup interface");return s;}
    void compatible(JSONObject old)throws Exception{if(old==null)return;if(!old.getString("certificate").equals(release.getString("certificate")))throw new IOException("Different signing key. Nothing will be uninstalled.");if(old.getLong("versionCode")>release.getInt("versionCode"))throw new IOException("Newer launcher installed. Downgrades are blocked.");}
    static boolean same(JSONObject a,JSONObject b)throws Exception{return a==null?b==null:b!=null&&SetupPolicy.canonical(a).equals(SetupPolicy.canonical(b));}
    JSONObject review(JSONObject choices)throws Exception{
        trusted();JSONObject previous=journal.last();if(previous!=null&&!Arrays.asList("reviewed","kept","reverted","restored","checked","installed-no-preview").contains(previous.optString("state")))throw new IOException("Check the saved operation before starting another one");
        SetupPolicy.fields(choices,"style","position","size","spacing","wallpaper","apps");List<String> wanted=new ArrayList<>();JSONArray apps=choices.getJSONArray("apps");for(int n=0;n<apps.length();n++)wanted.add(apps.getString(n));JSONObject normalized=SetupPolicy.choices(choices.getString("style"),choices.getString("position"),choices.getString("size"),choices.getString("spacing"),wanted);if(!same(normalized,choices)||!device.apps().containsAll(wanted))throw new IOException("An app or setup choice is unavailable");
        if(device.api()<release.getInt("minSdk"))throw new IOException("This TV needs Android 8 or newer");String id=UUID.randomUUID().toString().replace("-","");JSONObject old=device.installed(new File(root,id+"-before.apk"));compatible(old);JSONObject nativeBefore=old==null?null:nativeStatus();if(nativeBefore!=null&&!nativeBefore.isNull("pending"))throw new IOException("Finish the existing TV preview first");
        JSONObject r=new JSONObject().put("schema",1).put("id",id).put("state","reviewed").put("device",device.fingerprint()).put("peer",device.peer()).put("originalHome",SetupPolicy.component(device.home())).put("release",release).put("choices",normalized).put("installed",old==null?JSONObject.NULL:old).put("backup",nativeBefore==null?JSONObject.NULL:nativeBefore.getJSONObject("backup")).put("profile",nativeBefore==null?"":nativeBefore.getString("profile")).put("revision",nativeBefore==null?"":nativeBefore.getString("revision"));
        r.put("planHash",SetupPolicy.sha(SetupPolicy.canonical(r).getBytes(java.nio.charset.StandardCharsets.UTF_8)));journal.append(r);reviewed=new JSONObject(r.toString());return new JSONObject(r.toString());
    }
    void bound(JSONObject r)throws Exception{SetupPolicy.component(r.getString("originalHome"));trusted();if(!device.fingerprint().equals(r.getString("device"))||!device.peer().equals(r.getString("peer")))throw new IOException("TV identity changed. No operation was sent.");if(!same(r.getJSONObject("release"),release)||!SetupPolicy.sha(Files.readAllBytes(apk.toPath())).equals(release.getString("sha256")))throw new IOException("Signed release changed; review again");}
    void record(JSONObject r,String state)throws Exception{r.put("state",state);journal.append(r);}
    JSONObject install(String approvedPlanHash)throws Exception{
        JSONObject r=reviewed;reviewed=null;if(r==null||!r.getString("planHash").equals(approvedPlanHash))throw new IOException("Review this plan again");
        try{
            bound(r);if(!device.home().equals(r.getString("originalHome")))throw new IOException("Home changed after review");JSONObject current=device.installed(new File(root,r.getString("id")+"-checked.apk")),old=r.isNull("installed")?null:r.getJSONObject("installed");if(!same(old,current))throw new IOException("Installed launcher changed after review");if(current!=null){JSONObject s=nativeStatus();if(!r.getString("revision").equals(s.getString("revision"))||!r.getString("profile").equals(s.getString("profile")))throw new IOException("Launcher settings changed after review");}
            record(r,"installing");device.install(apk,release.getString("sha256"));device.preserveHome(r.getString("originalHome"));verifyInstalled(r);record(r,"installed");device.launch();JSONObject s=nativeStatus();if(r.isNull("backup")){r.put("backup",s.getJSONObject("backup")).put("profile",s.getString("profile")).put("revision",s.getString("revision"));record(r,"installed");}return preview(r,s);
        }catch(Exception e){record(r,"needs-attention");throw e;}
    }
    void verifyInstalled(JSONObject r)throws Exception{JSONObject now=device.installed(new File(root,r.getString("id")+"-installed.apk"));if(now==null||!now.getString("sha256").equals(release.getString("sha256"))||!now.getString("certificate").equals(release.getString("certificate"))||now.getLong("versionCode")!=release.getInt("versionCode"))throw new IOException("Installed APK does not match the reviewed release");}
    JSONObject preview(JSONObject r,JSONObject state)throws Exception{if(!state.isNull("pending"))throw new IOException("A TV preview is already active");record(r,"previewing");JSONObject request=new JSONObject().put("revision",state.getString("revision")).put("profile",state.getString("profile")).put("requestId",r.getString("id")).put("choices",r.getJSONObject("choices"));device.nativeCall("preview",request);record(r,"awaiting-tv");return r;}
    JSONObject check()throws Exception{JSONObject r=journal.last();if(r==null)throw new IOException("No saved setup operation");bound(r);JSONObject observed=device.installed(new File(root,r.getString("id")+"-recovered.apk"));if(observed==null||!observed.optString("sha256").equals(release.getString("sha256"))){JSONObject before=r.isNull("installed")?null:r.getJSONObject("installed");if(same(before,observed)&&device.home().equals(r.getString("originalHome"))){record(r,"checked");return r;}throw new IOException("Install result differs from the reviewed release; manual recovery required");}verifyInstalled(r);JSONObject s=nativeStatus();if("restored".equals(r.optString("state"))&&r.getJSONObject("backup").getString("profile").equals(s.getString("profile")))return r;JSONObject pending=s.optJSONObject("pending");if(pending!=null&&r.getString("id").equals(pending.optString("requestId")))record(r,"awaiting-tv");else{String result=s.optString("result");JSONObject receipt=result.startsWith("{")?new JSONObject(result):new JSONObject();if(r.getString("id").equals(receipt.optString("requestId"))&&Arrays.asList("kept","reverted").contains(receipt.optString("outcome")))record(r,receipt.getString("outcome"));else record(r,"installed-no-preview");}return r;}
    JSONObject resumePreview()throws Exception{JSONObject r=check();if(!r.getString("state").equals("installed-no-preview"))throw new IOException("Check or finish the existing preview");JSONObject s=nativeStatus();if(!r.getString("revision").isEmpty()&&!r.getString("revision").equals(s.getString("revision")))throw new IOException("Home settings changed. Review a new plan instead.");if(r.isNull("backup"))r.put("backup",s.getJSONObject("backup"));return preview(r,s);}
    JSONObject reviewRestore(String id)throws Exception{JSONObject r=journal.last();if(r==null||!r.getString("id").equals(id)||r.isNull("backup"))throw new IOException("No matching saved backup");bound(r);verifyInstalled(r);JSONObject s=nativeStatus();if(!s.isNull("pending"))throw new IOException("Revert the TV preview before restoring");return new JSONObject().put("id",id).put("revision",s.getString("revision")).put("profile",r.getJSONObject("backup").getString("profile"));}
    JSONObject restore(String approvedId,String approvedRevision)throws Exception{JSONObject r=journal.last();if(r==null||!r.getString("id").equals(approvedId)||r.isNull("backup"))throw new IOException("Review a saved backup first");bound(r);verifyInstalled(r);JSONObject s=nativeStatus();if(!s.isNull("pending"))throw new IOException("Revert the TV preview before restoring");if(!s.getString("revision").equals(approvedRevision))throw new IOException("Settings changed after restore review; review again");record(r,"restoring");JSONObject after=device.nativeCall("restore",new JSONObject().put("revision",s.getString("revision")).put("backup",r.getJSONObject("backup")));if(!after.getString("profile").equals(r.getJSONObject("backup").getString("profile")))throw new IOException("Restore needs checking on TV");record(r,"restored");return r;}
}
